using FHeroes2.Assets.Maps;
using FHeroes2.Core.Geometry;

namespace FHeroes2.Game.Maps;

/// <summary>
/// The object tables of the reference, apart from the ones that are hand-written: roads, streams
/// and trees (<c>MapObjectCatalog.Roads.cs</c>, <c>MapObjectCatalog.Landscape.cs</c>), kingdom
/// towns (<c>MapObjectCatalog.Kingdom.cs</c>), monsters (<c>MapObjectCatalog.Monsters.cs</c>) and
/// artifacts (<c>MapObjectCatalog.Artifacts.cs</c>).
///
/// <para>
/// Generated by <c>tools/scripts/GenerateMapObjectTables.ps1</c> and must not be edited by hand:
/// one C# line per line of <c>src/fheroes2/maps/map_object_info.cpp</c>, in the same order, and
/// the order is part of the map format. Re-run the script only when the reference checkout moves,
/// then run <c>MapObjectCatalogTests</c>, which pins the size of every table.
/// </para>
/// </summary>
public static partial class MapObjectCatalog
{

    /// <summary><c>populateLandscapeMountains</c> of the reference, one line per reference line.</summary>
    /// <param name="objects">Table of the group, must be empty.</param>
    private static void PopulateLandscapeMountains(List<ObjectInfo> objects)
    {
        // Grouped mountains have different appearances: Generic, Grass, Snow, Swamp, Lava, Desert, Dirt, Wasteland.
        foreach (Mp2ObjectIcnType type in new[] { Mp2ObjectIcnType.MtnMult, Mp2ObjectIcnType.MtnGras, Mp2ObjectIcnType.MtnSnow, Mp2ObjectIcnType.MtnSwmp, Mp2ObjectIcnType.MtnLava, Mp2ObjectIcnType.MtnDsrt, Mp2ObjectIcnType.MtnDirt, Mp2ObjectIcnType.MtnCrck })
        {
            // Big mountain from top-left to bottom-right.
            {
                ObjectInfo objectInfo = new(Mp2ObjectType.Mountains);
                objectInfo.AddGroundPart(type, 14U, new Point(0, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 6U, new Point(-2, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 7U, new Point(-1, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 8U, new Point(0, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 9U, new Point(1, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 12U, new Point(-2, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 13U, new Point(-1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 15U, new Point(1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 16U, new Point(2, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 18U, new Point(0, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 19U, new Point(1, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 20U, new Point(2, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, 0U, new Point(-3, -2), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, 5U, new Point(-3, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, 11U, new Point(-3, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, 17U, new Point(-1, 1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddTopPart(type, 1U, new Point(-2, -2), Mp2ObjectType.Mountains);
                objectInfo.AddTopPart(type, 2U, new Point(-1, -2), Mp2ObjectType.Mountains);
                objectInfo.AddTopPart(type, 3U, new Point(0, -2), Mp2ObjectType.Mountains);
                objectInfo.AddTopPart(type, 4U, new Point(1, -2), Mp2ObjectType.Mountains);
                objectInfo.AddTopPart(type, 10U, new Point(2, -1), Mp2ObjectType.Mountains);
                objects.Add(objectInfo);
            }
            uint icnOffset = 21U;
            // Big mountain from top-right to bottom-left.
            {
                ObjectInfo objectInfo = new(Mp2ObjectType.Mountains);
                objectInfo.AddGroundPart(type, icnOffset + 14U, new Point(0, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 7U, new Point(-1, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 8U, new Point(0, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 9U, new Point(1, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 10U, new Point(2, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 12U, new Point(-2, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 13U, new Point(-1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 15U, new Point(1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 16U, new Point(2, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 18U, new Point(-2, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 19U, new Point(-1, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 20U, new Point(0, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 0U, new Point(-2, -2), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, icnOffset + 5U, new Point(-3, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, icnOffset + 11U, new Point(-3, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, icnOffset + 17U, new Point(-3, 1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddTopPart(type, icnOffset + 1U, new Point(-1, -2), Mp2ObjectType.Mountains);
                objectInfo.AddTopPart(type, icnOffset + 2U, new Point(0, -2), Mp2ObjectType.Mountains);
                objectInfo.AddTopPart(type, icnOffset + 3U, new Point(1, -2), Mp2ObjectType.Mountains);
                objectInfo.AddTopPart(type, icnOffset + 4U, new Point(2, -2), Mp2ObjectType.Mountains);
                objectInfo.AddTopPart(type, icnOffset + 6U, new Point(-2, -1), Mp2ObjectType.Mountains);
                objects.Add(objectInfo);
            }
            icnOffset += 21;
            // Dirt and Wasteland has extra mountains placed in ICN between big and small mountains
            if (type == Mp2ObjectIcnType.MtnDirt || type == Mp2ObjectIcnType.MtnCrck)
            {
                // Extra mountain from top-left to bottom-right.
                {
                    ObjectInfo objectInfo = new(Mp2ObjectType.Mountains);
                    objectInfo.AddGroundPart(type, icnOffset + 8U, new Point(0, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 6U, new Point(-2, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 7U, new Point(-1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 12U, new Point(0, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 13U, new Point(1, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 14U, new Point(2, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 0U, new Point(-3, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                    objectInfo.AddGroundPart(type, icnOffset + 4U, new Point(1, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                    objectInfo.AddGroundPart(type, icnOffset + 5U, new Point(-3, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
                    objectInfo.AddGroundPart(type, icnOffset + 11U, new Point(-1, 1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                    objectInfo.AddTopPart(type, icnOffset + 1U, new Point(-2, -1), Mp2ObjectType.Mountains);
                    objectInfo.AddTopPart(type, icnOffset + 2U, new Point(-1, -1), Mp2ObjectType.Mountains);
                    objectInfo.AddTopPart(type, icnOffset + 3U, new Point(0, -1), Mp2ObjectType.Mountains);
                    objectInfo.AddTopPart(type, icnOffset + 9U, new Point(1, 0), Mp2ObjectType.Mountains);
                    objectInfo.AddTopPart(type, icnOffset + 10U, new Point(2, 0), Mp2ObjectType.Mountains);
                    objects.Add(objectInfo);
                }
                icnOffset += 15;
                // Extra mountain from top-right to bottom-left.
                {
                    ObjectInfo objectInfo = new(Mp2ObjectType.Mountains);
                    objectInfo.AddGroundPart(type, icnOffset + 8U, new Point(0, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 9U, new Point(1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 10U, new Point(2, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 12U, new Point(-2, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 13U, new Point(-1, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 14U, new Point(0, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 0U, new Point(-2, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                    objectInfo.AddGroundPart(type, icnOffset + 1U, new Point(-1, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                    objectInfo.AddGroundPart(type, icnOffset + 5U, new Point(-3, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
                    objectInfo.AddGroundPart(type, icnOffset + 11U, new Point(-3, 1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                    objectInfo.AddTopPart(type, icnOffset + 2U, new Point(0, -1), Mp2ObjectType.Mountains);
                    objectInfo.AddTopPart(type, icnOffset + 3U, new Point(1, -1), Mp2ObjectType.Mountains);
                    objectInfo.AddTopPart(type, icnOffset + 4U, new Point(2, -1), Mp2ObjectType.Mountains);
                    objectInfo.AddTopPart(type, icnOffset + 6U, new Point(-2, 0), Mp2ObjectType.Mountains);
                    objectInfo.AddTopPart(type, icnOffset + 7U, new Point(-1, 0), Mp2ObjectType.Mountains);
                    objects.Add(objectInfo);
                }
                icnOffset += 15;
            }
            // Medium mountain from top-left to bottom-right.
            {
                ObjectInfo objectInfo = new(Mp2ObjectType.Mountains);
                objectInfo.AddGroundPart(type, icnOffset + 5U, new Point(0, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 4U, new Point(-1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 6U, new Point(1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 8U, new Point(0, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 9U, new Point(1, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 0U, new Point(-2, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, icnOffset + 3U, new Point(-2, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, icnOffset + 7U, new Point(-1, 1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                // Grassy medium mountain should not be passable in the upper row (according to its image)
                if (type == Mp2ObjectIcnType.MtnGras)
                {
                    objectInfo.AddGroundPart(type, icnOffset + 1U, new Point(-1, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 2U, new Point(0, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                }
                else
                {
                    objectInfo.AddTopPart(type, icnOffset + 1U, new Point(-1, -1), Mp2ObjectType.Mountains);
                    objectInfo.AddTopPart(type, icnOffset + 2U, new Point(0, -1), Mp2ObjectType.Mountains);
                }
                objects.Add(objectInfo);
            }
            icnOffset += 10;
            // Medium mountain from top-left to bottom-right.
            {
                ObjectInfo objectInfo = new(Mp2ObjectType.Mountains);
                objectInfo.AddGroundPart(type, icnOffset + 5U, new Point(0, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                if (type == Mp2ObjectIcnType.MtnCrck)
                {
                    objectInfo.AddTopPart(type, icnOffset + 4U, new Point(-1, 0), Mp2ObjectType.Mountains);
                }
                else
                {
                    objectInfo.AddGroundPart(type, icnOffset + 4U, new Point(-1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                }
                objectInfo.AddGroundPart(type, icnOffset + 6U, new Point(1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 8U, new Point(-1, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 9U, new Point(0, 1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 0U, new Point(-1, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, icnOffset + 3U, new Point(-2, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, icnOffset + 7U, new Point(-2, 1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                // Grassy medium mountain should not be passable in the upper row (according to its image)
                if (type == Mp2ObjectIcnType.MtnGras)
                {
                    objectInfo.AddGroundPart(type, icnOffset + 1U, new Point(0, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                    objectInfo.AddGroundPart(type, icnOffset + 2U, new Point(1, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                }
                else
                {
                    objectInfo.AddTopPart(type, icnOffset + 1U, new Point(0, -1), Mp2ObjectType.Mountains);
                    objectInfo.AddTopPart(type, icnOffset + 2U, new Point(1, -1), Mp2ObjectType.Mountains);
                }
                objects.Add(objectInfo);
            }
            icnOffset += 10;
            // Small mountain from top-left to bottom-right.
            {
                ObjectInfo objectInfo = new(Mp2ObjectType.Mountains);
                objectInfo.AddGroundPart(type, icnOffset + 4U, new Point(0, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 1U, new Point(-1, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 2U, new Point(0, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 5U, new Point(1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 0U, new Point(-2, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, icnOffset + 3U, new Point(-1, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objects.Add(objectInfo);
            }
            icnOffset += 6;
            // Small mountain from top-right to bottom-left.
            {
                ObjectInfo objectInfo = new(Mp2ObjectType.Mountains);
                objectInfo.AddGroundPart(type, icnOffset + 5U, new Point(0, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 1U, new Point(0, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 2U, new Point(1, -1), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 4U, new Point(-1, 0), Mp2ObjectType.Mountains, ObjectLayerType.Object);
                objectInfo.AddGroundPart(type, icnOffset + 0U, new Point(-1, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objectInfo.AddGroundPart(type, icnOffset + 3U, new Point(-2, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
                objects.Add(objectInfo);
            }
        }
        // Single mountains.
        // Grass medium mound.
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.Mound);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnGras, 77U, new Point(0, 0), Mp2ObjectType.Mound, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnGras, 78U, new Point(1, 0), Mp2ObjectType.Mound, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnGras, 76U, new Point(-1, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objects.Add(objectInfo);
        }
        // Grass small mound.
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.Mound);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnGras, 149U, new Point(0, 0), Mp2ObjectType.Mound, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnGras, 150U, new Point(1, 0), Mp2ObjectType.Mound, ObjectLayerType.Object);
            objects.Add(objectInfo);
        }
        // Big volcano (Lava terrain).
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.Volcano);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav3, 245U, new Point(0, 0), Mp2ObjectType.Volcano, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav3, 244U, new Point(-1, 0), Mp2ObjectType.Volcano, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav3, 246U, new Point(1, 0), Mp2ObjectType.Volcano, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav3, 120U, new Point(-4, -2), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav3, 180U, new Point(-5, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav3, 195U, new Point(-4, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav3, 210U, new Point(-3, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav3, 225U, new Point(-2, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav3, 243U, new Point(-2, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 0U, new Point(-1, -4), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 15U, new Point(0, -4), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 30U, new Point(1, -4), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 45U, new Point(-2, -3), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 60U, new Point(-1, -3), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 75U, new Point(0, -3), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 90U, new Point(1, -3), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 105U, new Point(2, -3), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 135U, new Point(-1, -2), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 150U, new Point(0, -2), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 165U, new Point(1, -2), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 14;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 240U, new Point(-1, -1), Mp2ObjectType.Volcano);
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 241U, new Point(0, -1), Mp2ObjectType.Volcano);
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav3, 242U, new Point(1, -1), Mp2ObjectType.Volcano);
            objects.Add(objectInfo);
        }
        // Middle volcano (Lava terrain).
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.Volcano);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 31U, new Point(0, 0), Mp2ObjectType.Volcano, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 30U, new Point(-1, 0), Mp2ObjectType.Volcano, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 32U, new Point(1, 0), Mp2ObjectType.Volcano, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 7U, new Point(-3, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 6;
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 14U, new Point(-2, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 6;
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 28U, new Point(1, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 29U, new Point(-2, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav2, 0U, new Point(0, -2), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 6;
            objectInfo.AddTopPart(Mp2ObjectIcnType.ObjnLav2, 21U, new Point(0, -1), Mp2ObjectType.Volcano);
            objectInfo.TopLevelParts[^1].AnimationFrames = 6;
            objects.Add(objectInfo);
        }
        // Small volcano (Lava terrain).
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.Volcano);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 80U, new Point(0, 0), Mp2ObjectType.Volcano, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 79U, new Point(-1, 0), Mp2ObjectType.Volcano, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 81U, new Point(1, 0), Mp2ObjectType.Volcano, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnLav2, 44U, new Point(-3, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
