    /// <summary><c>populateLandscapeTownBasements</c> of the reference, one line per reference line.</summary>
    /// <param name="objects">Table of the group, must be empty.</param>
    private static void PopulateLandscapeTownBasements(List<ObjectInfo> objects)
    {
        // Castle/town basement in the next order: grass, snow, swamp, lava, desert, dirt, wasteland, beach.
        for (uint basement = 0; basement < 8; ++basement)
        {
            uint icnOffset = (uint)(basement * 10);
            ObjectInfo objectInfo = new(Mp2ObjectType.Castle);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnTwba, icnOffset + 2, new Point(0, 0), Mp2ObjectType.Castle, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnTwba, icnOffset + 0, new Point(-2, 0), Mp2ObjectType.Castle, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnTwba, icnOffset + 1, new Point(-1, 0), Mp2ObjectType.Castle, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnTwba, icnOffset + 3, new Point(1, 0), Mp2ObjectType.Castle, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnTwba, icnOffset + 4, new Point(2, 0), Mp2ObjectType.Castle, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnTwba, icnOffset + 5, new Point(-2, 1), Mp2ObjectType.Castle, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnTwba, icnOffset + 6, new Point(-1, 1), Mp2ObjectType.Castle, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnTwba, icnOffset + 7, new Point(0, 1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnTwba, icnOffset + 8, new Point(1, 1), Mp2ObjectType.Castle, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnTwba, icnOffset + 9, new Point(2, 1), Mp2ObjectType.Castle, ObjectLayerType.Object);
            objects.Add(objectInfo);
        }
    }

    /// <summary><c>populateLandscapeFlags</c> of the reference, one line per reference line.</summary>
    /// <param name="objects">Table of the group, must be empty.</param>
    private static void PopulateLandscapeFlags(List<ObjectInfo> objects)
    {
        // Castle flags located one tile to the left and right from the castle entrance: blue, green, red, yellow, orange, purple, gray (neutral).
        for (uint color = 0; color < 7; ++color)
        {
            uint icnOffset = (uint)(color * 2);
            {
                // Left flag.
                ObjectInfo objectInfo = new(Mp2ObjectType.Castle);
                objectInfo.AddGroundPart(Mp2ObjectIcnType.Flag32, icnOffset, new Point(0, 0), Mp2ObjectType.Castle, ObjectLayerType.Object);
                objectInfo.Metadata[0] = color;
                objects.Add(objectInfo);
            }
            {
                // Right flag.
                ObjectInfo objectInfo = new(Mp2ObjectType.Castle);
                objectInfo.AddGroundPart(Mp2ObjectIcnType.Flag32, icnOffset + 1, new Point(0, 0), Mp2ObjectType.Castle, ObjectLayerType.Object);
                objectInfo.Metadata[0] = color;
                objects.Add(objectInfo);
            }
        }
        // TODO: Add flags for other capture-able objects.
    }

