    /// <summary><c>populateAdventureMines</c> of the reference, one line per reference line.</summary>
    /// <param name="objects">Table of the group, must be empty.</param>
    private static void PopulateAdventureMines(List<ObjectInfo> objects)
    {
        // Mines provide 5 resources: Ore, Sulfur, Crystal, Gems, Gold.
        uint mineResources = 5;
        // Mines have different appearances: Generic, Grass, Snow, Swamp, Lava, Desert, Dirt, Wasteland.
        foreach (var (type, offset) in new[] { (Mp2ObjectIcnType.MtnMult, 74U), (Mp2ObjectIcnType.MtnGras, 74U), (Mp2ObjectIcnType.MtnSnow, 74U), (Mp2ObjectIcnType.MtnSwmp, 74U), (Mp2ObjectIcnType.MtnLava, 74U), (Mp2ObjectIcnType.MtnDsrt, 74U), (Mp2ObjectIcnType.MtnDirt, 104U), (Mp2ObjectIcnType.MtnCrck, 104U) })
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.ActionMine);
            objectInfo.AddGroundPart(type, offset + 8U, new Point(0, 0), Mp2ObjectType.ActionMine, ObjectLayerType.Object);
            objectInfo.AddGroundPart(type, offset + 4U, new Point(1, -1), Mp2ObjectType.Mine, ObjectLayerType.Object);
            objectInfo.AddGroundPart(type, offset + 7U, new Point(-1, 0), Mp2ObjectType.Mine, ObjectLayerType.Object);
            objectInfo.AddGroundPart(type, offset + 9U, new Point(1, 0), Mp2ObjectType.Mine, ObjectLayerType.Object);
            objectInfo.AddGroundPart(type, offset + 0U, new Point(-3, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddGroundPart(type, offset + 1U, new Point(-2, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddGroundPart(type, offset + 5U, new Point(-3, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddGroundPart(type, offset + 6U, new Point(-2, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddTopPart(type, offset + 2U, new Point(-1, -1), Mp2ObjectType.Mine);
            objectInfo.AddTopPart(type, offset + 3U, new Point(0, -1), Mp2ObjectType.Mine);
            // The carts with these resources are placed above the main mine tile.
            for (uint resource = 0; resource < mineResources; ++resource)
            {
                objectInfo.AddGroundPart(Mp2ObjectIcnType.ExtraOvr, resource, new Point(0, 0), Mp2ObjectType.ActionMine, ObjectLayerType.Object);
                // Set the metadata: 0 - resource type, 1 - income per day.
                switch (resource)
                {
                    case 0:
                        objectInfo.Metadata[0] = (uint)Mp2ResourceType.Ore;
                        objectInfo.Metadata[1] = 2;
                        break;
                    case 1:
                        objectInfo.Metadata[0] = (uint)Mp2ResourceType.Sulfur;
                        objectInfo.Metadata[1] = 1;
                        break;
                    case 2:
                        objectInfo.Metadata[0] = (uint)Mp2ResourceType.Crystal;
                        objectInfo.Metadata[1] = 1;
                        break;
                    case 3:
                        objectInfo.Metadata[0] = (uint)Mp2ResourceType.Gems;
                        objectInfo.Metadata[1] = 1;
                        break;
                    case 4:
                        objectInfo.Metadata[0] = (uint)Mp2ResourceType.Gold;
                        objectInfo.Metadata[1] = 1000;
                        break;
                    default:
                        // Have you added a new mine resource?! Update the logic above!
                        break;
                }
                if (resource < mineResources - 1)
                {
                    objects.Add(objectInfo.Copy());
                    // Remove the resource from the mine to add a new one in the next loop.
                    objectInfo.GroundLevelParts.RemoveAt(objectInfo.GroundLevelParts.Count - 1);
                }
            }
            // The last resource with the current mine appearance type.
            objects.Add(objectInfo);
        }
        // Abandoned Mine: Generic.
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.ActionAbandonedMine);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.MtnMult, 92U, new Point(0, 0), Mp2ObjectType.ActionAbandonedMine, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.MtnMult, 88U, new Point(1, -1), Mp2ObjectType.AbandonedMine, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.MtnMult, 91U, new Point(-1, 0), Mp2ObjectType.AbandonedMine, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.MtnMult, 93U, new Point(1, 0), Mp2ObjectType.AbandonedMine, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.MtnMult, 84U, new Point(-3, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.MtnMult, 85U, new Point(-2, -1), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.MtnMult, 89U, new Point(-3, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.MtnMult, 90U, new Point(-2, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
