            objects.Add(objectInfo);
        }
        // Abandoned Mines: Snow, Swamp, Lava and Desert.
        foreach (Mp2ObjectIcnType type in new[] { Mp2ObjectIcnType.MtnSnow, Mp2ObjectIcnType.MtnSwmp, Mp2ObjectIcnType.MtnLava, Mp2ObjectIcnType.MtnDsrt })
