    /// <summary><c>populateAdventureTreasures</c> of the reference, one line per reference line.</summary>
    /// <param name="objects">Table of the group, must be empty.</param>
    private static void PopulateAdventureTreasures(List<ObjectInfo> objects)
    {
        // Normal resources.
        int resourceImageIndex = 1;
        foreach (Mp2ResourceType resource in new[] { Mp2ResourceType.Wood, Mp2ResourceType.Mercury, Mp2ResourceType.Ore, Mp2ResourceType.Sulfur, Mp2ResourceType.Crystal, Mp2ResourceType.Gems, Mp2ResourceType.Gold })
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.ActionResource);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnRsrc, (uint)(resourceImageIndex), new Point(0, 0), Mp2ObjectType.ActionResource, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnRsrc, (uint)(resourceImageIndex - 1), new Point(-1, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.Metadata[0] = (uint)resource;
            objects.Add(objectInfo);
            resourceImageIndex += 2;
        }
        // Genie's Lamp.
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.ActionGenieLamp);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnRsrc, 15, new Point(0, 0), Mp2ObjectType.ActionGenieLamp, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnRsrc, 14, new Point(-1, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objects.Add(objectInfo);
        }
        // Random resource.
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.ActionRandomResource);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnRsrc, 17, new Point(0, 0), Mp2ObjectType.ActionRandomResource, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnRsrc, 16, new Point(-1, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objects.Add(objectInfo);
        }
        // Treasure chest.
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.ActionTreasureChest);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnRsrc, 19, new Point(0, 0), Mp2ObjectType.ActionTreasureChest, ObjectLayerType.Object);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnRsrc, 18, new Point(-1, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objects.Add(objectInfo);
        }
        // Campfire.
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.ActionCampfire);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnMult, 131, new Point(0, 0), Mp2ObjectType.ActionCampfire, ObjectLayerType.Object);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 6;
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnMult, 124, new Point(-1, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 6;
            objects.Add(objectInfo);
        }
        // Campfire on show.
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.ActionCampfire);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnSnow, 4, new Point(0, 0), Mp2ObjectType.ActionCampfire, ObjectLayerType.Object);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 6;
            // The original resources do not have a part of shadow for this object so we use the same shadow from another campfire.
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnDsrt, 54, new Point(-1, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 6;
            objects.Add(objectInfo);
        }
        // Campfire in desert.
        {
            ObjectInfo objectInfo = new(Mp2ObjectType.ActionCampfire);
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnDsrt, 61, new Point(0, 0), Mp2ObjectType.ActionCampfire, ObjectLayerType.Object);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 6;
            objectInfo.AddGroundPart(Mp2ObjectIcnType.ObjnDsrt, 54, new Point(-1, 0), Mp2ObjectType.None, ObjectLayerType.Shadow);
            objectInfo.GroundLevelParts[^1].AnimationFrames = 6;
            objects.Add(objectInfo);
        }
    }

