    /// <summary><c>populateKingdomHeroes</c> of the reference, one line per reference line.</summary>
    /// <param name="objects">Table of the group, must be empty.</param>
    private static void PopulateKingdomHeroes(List<ObjectInfo> objects)
    {
        // Only 7 races and 6 colors exist in the game.
        for (int color = 0; color < 6; ++color)
        {
            for (int race = 0; race < 7; ++race)
            {
                ObjectInfo objectInfo = new(Mp2ObjectType.ActionHero);
                objectInfo.AddGroundPart(Mp2ObjectIcnType.MiniHero, (uint)(color * 7 + race), new Point(0, 0), Mp2ObjectType.ActionHero, ObjectLayerType.Object);
                objectInfo.Metadata[0] = (uint)color;
                if (race == 6)
                {
                    // We need to set as a random race, not multi.
                    ++race;
                }
                objectInfo.Metadata[1] = (uint)race;
                objects.Add(objectInfo);
            }
        }
    }

